//
// Side FXy: anti-aliased bitmap fonts, generated by tools/make_fonts.py
// from DejaVu Sans (see LICENSE) into gfx/fonts.cc. Printable ASCII
// (0x20..0x7e) plus a few symbols mapped onto control codes:
//   \x01  a note (sync on), \x02 right triangle, \x03 left triangle,
//   \x04  a dot, \x05 a degree ring.

#ifndef SIDEFX_GFX_FONT_H_
#define SIDEFX_GFX_FONT_H_

#include <stdint.h>

namespace sidefx {

struct Glyph {
  uint32_t offset;   // into Font::bitmap, in bytes
  uint8_t width;     // bitmap size in pixels
  uint8_t height;
  int8_t x_offset;   // from the pen position to the bitmap's left
  int8_t y_offset;   // from the line box's top to the bitmap's top
  uint8_t advance;   // pen advance
};

struct Font {
  uint8_t first;        // first code in glyphs[]
  uint8_t last;         // last code
  uint8_t line_height;  // line box height
  uint8_t ascent;       // line box top to baseline
  const Glyph* glyphs;  // last - first + 1 entries
  const uint8_t* bitmap;  // 4-bit coverage, two pixels per byte (high nibble first), rows padded to whole bytes
};

extern const Font kFontSmall;   // ~11 px: row labels, status
extern const Font kFontMedium;  // ~15 px: names, lists
extern const Font kFontLarge;   // ~22 px bold: values
extern const Font kFontHuge;    // ~32 px bold: the preset number

}  // namespace sidefx

#endif  // SIDEFX_GFX_FONT_H_
